"""Standalone visual comparison for fixed-rate metric scenarios."""
import json
from pathlib import Path
import sys

HTML = '''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Metrics scenario benchmarks</title>
<style>*{box-sizing:border-box}body{background:#101010;color:#ddd;font:16px system-ui;margin:0;padding:32px}main{max-width:1700px;margin:auto;padding:36px;background:#202020;border:1px solid #383838;border-radius:20px}h1{margin:12px 0}p,small{color:#aaa}select{background:#303030;color:white;padding:12px;border:1px solid #555;border-radius:8px;font:inherit}.legend{display:flex;gap:32px;margin:28px 0}.dot{display:inline-block;width:14px;height:14px;border-radius:3px;margin-right:8px}svg{width:100%;height:auto}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:12px;border-bottom:1px solid #393939}a{color:#bbb}.note{line-height:1.6;background:#292929;padding:18px;border-radius:8px}</style>
<main><small>LOCAL PREVIEW · METRICS · RUST GENERATOR</small><h1>Pipeline Performance Benchmarks</h1><p>10,000 requests/sec × 512 points/request = 5.12 million points/sec · OTLP/gRPC input</p>
<select id="view"><option value="efficiency">Points/sec per core</option><option value="cpu">CPU cores</option><option value="rate">Points/sec reached</option></select>
<div class="legend"><span><i class="dot" style="background:#00cc66"></i>Edge Delta (Rust) · PR #20</span><span><i class="dot" style="background:#a348ff"></i>OpenTelemetry Collector · 0.162.0</span><span><i class="dot" style="background:#f04444"></i>Bindplane (Dynatrace) · 1.110.1</span></div><p id="caption"></p><svg id="chart" viewBox="0 0 1500 510"></svg><p class="note">30 seconds of input per trial, followed by delivery drain. CPU cost includes processing through the final flush, normalized to the input window. Dashed bars fell short of the offered load. N/A means operation or delivery verification failed; it is not a capability claim. Aggregation and rollup use native processing and flush behavior.</p><table><thead><tr><th>Scenario</th><th>Vendor</th><th>Requests/sec</th><th>CPU cost</th><th>Output points</th><th>Verification</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table><p>64 recurring resource groups × 64 host series. 64 input connections, up to 1,024 in-flight requests. Isolated c8i.8xlarge load, agent, and sink hosts. One trial per case. <a href="results.json">Download results</a></p></main>
<script>const data=__DATA__;const scenarios=['pass-through','filter','enrich','aggregate','rollup','combined'];const vendors=['red','otelcol','bindplane'];const names={red:'Edge Delta (Rust)',otelcol:'OpenTelemetry Collector',bindplane:'Bindplane (Dynatrace)'};const colors={red:'#00cc66',otelcol:'#a348ff',bindplane:'#f04444'};const fmt=n=>new Intl.NumberFormat('en-US',{notation:n>=10000?'compact':'standard',maximumFractionDigits:2}).format(n);
const cost=r=>r.through_delivery.cpu_seconds/r.input_window.elapsed_seconds;
function render(){const view=document.getElementById('view').value;const valid=r=>r&&r.load&&r.delivery_verified&&r.operation_verified;const value=r=>!valid(r)?0:view==='cpu'?cost(r):view==='rate'?r.load.achieved_rps*512:r.load.achieved_rps*512/cost(r);const max=Math.max(1,...data.rows.map(value))*1.18;let svg='';for(let i=0;i<5;i++){let y=420-i*90;svg+=`<line x1="85" x2="1490" y1="${y}" y2="${y}" stroke="#393939"/><text x="72" y="${y+5}" text-anchor="end" fill="#aaa">${fmt(max*i/4)}</text>`}
scenarios.forEach((scenario,i)=>{const base=110+i*230;vendors.forEach((v,j)=>{const r=data.rows.find(r=>r.scenario===scenario&&r.vendor===v),n=value(r),h=n/max*360,x=base+j*60,solid=r?.status==='measured';svg+=`<rect x="${x}" y="${420-h}" width="48" height="${h}" rx="4" fill="${colors[v]}" fill-opacity="${solid?1:.25}" stroke="${colors[v]}" ${solid?'':'stroke-dasharray="5 4"'}/><text x="${x+24}" y="${405-h}" text-anchor="middle" fill="#ccc" font-size="12">${valid(r)?fmt(n):'N/A'}</text>`});svg+=`<text x="${base+84}" y="465" text-anchor="middle" fill="#ddd">${scenario==='pass-through'?'Pass-Through':scenario[0].toUpperCase()+scenario.slice(1)}</text>`});document.getElementById('chart').innerHTML=svg;document.getElementById('caption').textContent=view==='cpu'?'CPU seconds per input-window second · lower is better':view==='rate'?'Input points/sec reached · higher is better':'Input points/sec per CPU core · higher is better';document.getElementById('rows').innerHTML=data.rows.map(r=>`<tr><td>${r.scenario}</td><td>${names[r.vendor]}</td><td>${r.load?fmt(r.load.achieved_rps):'—'}</td><td>${r.load?cost(r).toFixed(3):'—'}</td><td>${r.delivered?fmt(r.delivered.points):'—'}</td><td>${valid(r)?'Verified':'Not verified'}</td><td>${r.status.replaceAll('_',' ')}</td></tr>`).join('')};document.getElementById('view').onchange=render;render();</script>'''


def main():
    data=json.loads(Path(sys.argv[1]).read_text())
    out=Path(sys.argv[2]);out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(HTML.replace('__DATA__',json.dumps(data).replace('<','\\u003c')))


if __name__=='__main__':main()
